// Callable by any sub-workflow that hits an error -- classifies it into a stable code for
// this turn's own reply. $json.error may be either a raw error (string or {message}) needing
// classification, or an already-known code the caller decided itself (e.g. 'NO_MATCH') --
// recognized by an ALL_CAPS shape, left as-is rather than reclassified.
// $json.error_message, if present, overrides everything -- used when the caller already
// composed a specific, localized message (e.g. an LLM's own no_match reply).
const rawError = $json.error;
const errorText = (rawError && rawError.message) || String(rawError || '').trim();
const isKnownCode = typeof rawError === 'string' && /^[A-Z][A-Z_]*$/.test(rawError);
const error_type = isKnownCode ? rawError
  : /rate.?limit|tokens.?per.?min|TPM|too.?large/i.test(errorText) ? 'RATE_LIMIT'
  : /parse|json|syntax/i.test(errorText) ? 'PARSE_ERROR'
  : /not.?found|404/i.test(errorText) ? 'NOT_FOUND'
  : /unauthorized|403|401/i.test(errorText) ? 'AUTH_ERROR'
  : /process.?loop/i.test(errorText) ? 'PROCESS_LOOP'
  : 'UNKNOWN_ERROR';
const isExpert = $json.expertise_level === 3;
const MSG = {
  RATE_LIMIT:    { es: 'La búsqueda devolvió demasiados datos. Intenta con un criterio más específico.', en: 'The search returned too many results. Try a more specific criteria.' },
  PARSE_ERROR:   { es: 'Hubo un error procesando la respuesta. Intenta de nuevo.', en: 'There was an error processing the response. Please try again.' },
  NOT_FOUND:     { es: 'No se encontró la definición del proceso. Intenta de nuevo.', en: 'The process definition could not be loaded. Please try again.' },
  AUTH_ERROR:    { es: 'Error de autenticación. Contacta al administrador.', en: 'Authentication error. Please contact the administrator.' },
  PROCESS_LOOP:  { es: 'Este proceso no pudo completarse por un problema en su configuración y fue cancelado. Por favor intenta de nuevo o contacta a soporte si el problema persiste.', en: 'This process could not be completed due to a configuration issue and has been cancelled. Please try again or contact support if the problem persists.' },
};
const lang = $json.language || 'es';
// Every error_type above has a pre-written, reason-specific message -- only a code with no
// table entry (UNKNOWN_ERROR, or any ALL_CAPS code the caller invented without its own
// error_message) has nothing ready to show. Expert level gets the raw error verbatim in that
// case; every other level must never see either the raw text or a content-free "something
// went wrong" -- Needs Interpretation? routes those downstream to the agent instead, so
// message is deliberately left null here as the signal to do that, never defaulted inline.
let message = $json.error_message || MSG[error_type]?.[lang] || null;
if (!message && isExpert) {
  message = errorText;
}
const needsInterpretation = !message;
// AUTH_ERROR abandons whatever was active -- the abandoned node's own intention_nodes
// entry is left untouched (same pre-existing gap as before this restructure, not
// introduced by it), but active_node_id itself now auto-resumes to whatever this
// abandoned, instead of unconditionally dropping to null.
const clearState = error_type === 'AUTH_ERROR';
let activeNodeId = $json.active_node_id;
let intentionNodes = $json.intention_nodes || {};
let resetProcess = $json.reset_process === true;
if (clearState) {
  // Same TERMINAL_STATUSES/walk shape duplicated in Park Current Intent
  // (intent-manager.json), Compute Execution Outcome (sap-inquiry-execution.json),
  // Compute Form Outcome (sap-process-form-filling.json), and Resolve Final State
  // (batch-processing.json) -- keep all five in sync if this changes.
  const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
  const findResumeTarget = (nodeId, nodes) => {
    let current = nodeId;
    while (current) {
      const node = nodes[current];
      if (!node) return null;
      if (!TERMINAL_STATUSES.has(node.status)) return current;
      current = node.parent_id;
    }
    return null;
  };
  const activeNode = intentionNodes[$json.active_node_id] || {};
  const resumeTargetId = findResumeTarget(activeNode.parent_id, intentionNodes);
  if (resumeTargetId) {
    intentionNodes = { ...intentionNodes, [resumeTargetId]: { ...intentionNodes[resumeTargetId], status: 'active' } };
  }
  activeNodeId = resumeTargetId;
  // active_node_id must be forced through even when it lands on null (nothing to resume
  // to) -- Django's resettable merge otherwise coalesces an explicit null back to
  // whatever's already in Redis (main.py's _merge_field, resettable=True only lets null
  // through when reset_process is set).
  resetProcess = true;
}
return [{ json: {
  ...$json,
  message,
  errorText,
  needs_interpretation: needsInterpretation,
  active_node_id: activeNodeId,
  intention_nodes: intentionNodes,
  reset_process: resetProcess,
  error: error_type,
} }];

// Builds the prompt for Agent: Interpret Error. The raw error text is included only for the
// agent's own understanding -- its system message forbids quoting it back verbatim, so a
// non-expert user only ever sees what the error means for them, never the technical text.
const lang = $json.language || 'es';
const chatInput = `Explain, in ${lang}, what likely went wrong for the user and what they can do next.\n\nRAW ERROR (technical -- for your understanding only, never quote this verbatim):\n${$json.errorText}`;
return [{ json: { ...$json, chatInput } }];

// Parses Agent: Interpret Error's raw output text the same way the generic Extract JSON node
// does elsewhere in this file, then lifts its message onto the field Clear Route Key and every
// caller already read off Classify & Store Error. Falls back to a neutral, no-details message
// only if the agent's own output failed to parse (should be rare, e.g. onError fallthrough) --
// this path must never fall through to raw errorText, that's expert-only territory handled
// entirely upstream in Classify & Store Error.
const raw = $json.output || '';
let parsed = null;
try {
  parsed = JSON.parse(raw.trim());
} catch {
  try {
    const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
    parsed = JSON.parse(stripped);
  } catch {
    parsed = null;
  }
}
const lang = $json.language || 'es';
const FALLBACK = { es: 'Algo salió mal. Intenta de nuevo o contacta soporte.', en: 'Something went wrong. Please try again or contact support.' };
return [{ json: { ...$json, message: (parsed && parsed.message) || FALLBACK[lang] || FALLBACK.en } }];

// This turn is already fully handled (delivered directly below) -- null out route_key so
// the spine's Router safely falls through to its debug dead-end instead of dispatching
// (now to a real Intent Manager) on stale intent classification. Harmless no-op for any
// caller that never uses route_key in the first place.
return [{ json: { ...$json, route_key: null } }];

// Callable inline wherever a raw LLM `output` string needs to become JSON. Generic on
// purpose -- it only knows how to turn text into an object, not what shape that object
// should have (each agent's own file interprets _parsed itself). Safely inert when
// `output` is absent (e.g. called a second time after Compute X already ran) -- just
// yields _parsed: null, _parse_error: true, which nothing downstream reads in that case.
const raw = $json.output || '';
let content = null;
try {
  content = JSON.parse(raw.trim());
} catch {
  try {
    const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
    content = JSON.parse(stripped);
  } catch {
    content = null;
  }
}
if (content === null) {
  return [{ json: { ...$json, _parsed: null, _parse_error: true } }];
}
return [{ json: { ...$json, _parsed: content, _parse_error: false } }];
